-- Random boxes (Data/RBoxes/*.xml) e battle boxes (Data/BBoxes/*.xml) -> DB.
-- Idempotente: pode rodar mais de uma vez.

CREATE TABLE IF NOT EXISTS system_random_boxes (
    box_id      integer PRIMARY KEY,
    items_count integer NOT NULL DEFAULT 0,
    description text
);

CREATE TABLE IF NOT EXISTS system_random_box_rewards (
    box_id     integer NOT NULL,
    seq        integer NOT NULL,
    idx        integer NOT NULL,
    good_id    integer NOT NULL,
    percent    integer NOT NULL,
    is_special boolean NOT NULL DEFAULT false,
    PRIMARY KEY (box_id, seq)
);

CREATE TABLE IF NOT EXISTS system_battle_boxes (
    coupon_id    integer PRIMARY KEY,
    require_tags integer NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS system_battle_box_rewards (
    coupon_id integer NOT NULL,
    seq       integer NOT NULL,
    good_id   integer NOT NULL,
    percent   integer NOT NULL,
    PRIMARY KEY (coupon_id, seq)
);


ON CONFLICT (box_id) DO NOTHING;


ON CONFLICT (box_id, seq) DO NOTHING;


ON CONFLICT (coupon_id) DO NOTHING;


ON CONFLICT (coupon_id, seq) DO NOTHING;
